          position: relative;
          overflow: hidden;
        }

        .mood-insight-card:hover {
          transform: translateY(-5px);
          box-shadow: 0 12px 32px rgba(0, 0, 0, 0.1);
        }

        .mood-insight-icon {
          width: 50px;
          height: 50px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: ${moodGradients.main};
          color: white;
          font-size: 1.5rem;
          margin-bottom: 0.5rem;
        }

        .mood-insight-title {
          font-size: 1.2rem;
          font-weight: 600;
          color: #333;
          margin-bottom: 0.5rem;
        }

        .mood-insight-text {
          font-size: 1rem;
          color: #666;
          line-height: 1.6;
        }

        .insight-content {
          position: relative;
          height: 150px;
          overflow: hidden;
        }

        .insight-content-gradient {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          height: 50px;
          background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.9));
          pointer-events: none;
        }

        .insight-card-expand-hint {
          text-align: center;
          margin-top: 0.5rem;
          color: #43C6AC;
          font-weight: 500;
          font-size: 14px;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 4px;
          transition: all 0.3s ease;
          transform: translateY(5px);
          opacity: 0.7;
        }

        .mood-insight-card:hover .insight-card-expand-hint {
          transform: translateY(0);
          opacity: 1;
        }

        /* Modal stili */
        .insight-modal {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: rgba(0, 0, 0, 0.5);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 1000;
          padding: 1rem;
          animation: modalBounce 0.5s ease-out;
        }

        .modal-content {
          background: white;
          border-radius: 12px;
          max-width: 600px;
          width: 100%;
          max-height: 80vh;
          overflow-y: auto;
          padding: 2rem;
          position: relative;
          box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
        }

        .modal-close {
          position: absolute;
          top: 1rem;
          right: 1rem;
          background: none;
          border: none;
          font-size: 1.5rem;
          cursor: pointer;
          color: #aaa;
          transition: color 0.3s;
        }

        .modal-close:hover {
          color: #333;
        }

        .modal-header {
          display: flex;
          align-items: center;
          gap: 1rem;
          margin-bottom: 1.5rem;
          border-bottom: 1px solid #eee;
          padding-bottom: 1rem;
        }

        .modal-icon {
          width: 40px;
          height: 40px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: ${moodGradients.main};
          color: white;
          font-size: 1.2rem;
        }

        .modal-title {
          font-size: 1.5rem;
          font-weight: 600;
          color: #333;
        }

        .modal-body {
          font-size: 1rem;
          color: #666;
          line-height: 1.8;
        }

        .modal-body p {
          margin-bottom: 1rem;
        }

        @keyframes modalBounce {
          0% { transform: scale(0.8); opacity: 0; }
          50% { transform: scale(1.05); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
      `}</style>

      {/* Header */}
      <header className={`header mood-header ${scrolled ? 'scrolled' : ''}`}>
        <div className="container">
          <div className="flex justify-between items-center">
            <Link to="/" className="gradient-text text-2xl font-bold">
              Auralize
              <span className="logo-particle">✨</span>
            </Link>
            <nav>
              <ul className="flex space-x-6">
                <li><Link to="/gallery" className="nav-link">Galeri</Link></li>
                <li><Link to="/profile" className="nav-link">Profilim</Link></li>
              </ul>
            </nav>
          </div>
        </div>
      </header>

      <main className="main-content mood-result-content">
        <div className="container">
          <h1 className="mood-result-title">{insights.auraTitle || 'Duygu Durum Analizi'}</h1>

          {/* Hikaye Bölümü */}
          <section className="mood-section">
            <div className="mood-section-header">
              <h2 className="mood-section-title">
                <span className="mood-section-icon">💭</span> Duygusal Durum Hikayen
              </h2>
            </div>

            <div className="mood-story-box glass-card">
              {isStoryLoading ? (
                <div className="aura-loading-container">
                  <LoadingAnimation text="Duygusal durum analiziniz hazırlanıyor" color={moodGradients.main} />
                </div>
              ) : (
                <div className="mood-story-content animate__animated animate__fadeIn">
                  <div className="mood-story-text">
                    {moodStory.split('\n\n').map((paragraph, index) => (
                      <p key={index}>{paragraph}</p>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </section>

          {/* İçgörüler Bölümü */}
          <section className="mood-section">
            <div className="mood-section-header">
              <h2 className="mood-section-title">
                <span className="mood-section-icon">💡</span> Duygu Durumu İçgörülerin
              </h2>
            </div>

            <div className="mood-insights-grid">
              <div 
                className="mood-insight-card"
                onClick={() => openInsightModal('strengths')}
              >
                {isInsightsLoading ? (
                  <InsightLoadingSkeleton 
                    icon="💪" 
                    title="Duygusal Güçler" 
                    color={moodGradients.main}
                  />
                ) : (
                  <>
                    <div className="mood-insight-icon">💪</div>
                    <h3 className="mood-insight-title">Duygusal Güçler</h3>
                    <div className="insight-content">
                      <div className="insight-content-gradient"></div>
                      <p className="mood-insight-text">
                        {insights.strengths.substring(0, 100)}... <span className="read-more">Devamını Oku</span>
                      </p>
                    </div>
                    <div className="insight-card-expand-hint">
                      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M15 3h6v6"></path>
                        <path d="M10 14 21 3"></path>
                      </svg>
                      Daha Fazla Göster
                    </div>
                  </>
                )}
              </div>

              <div 
                className="mood-insight-card"
                onClick={() => openInsightModal('potential')}
              >
                {isInsightsLoading ? (
                  <InsightLoadingSkeleton 
                    icon="✨" 
                    title="Duygusal Potansiyel" 
                    color={moodGradients.main}
                  />
                ) : (
                  <>
                    <div className="mood-insight-icon">✨</div>
                    <h3 className="mood-insight-title">Duygusal Potansiyel</h3>
                    <div className="insight-content">
                      <div className="insight-content-gradient"></div>
                      <p className="mood-insight-text">
                        {insights.potential.substring(0, 100)}... <span className="read-more">Devamını Oku</span>
                      </p>
                    </div>
                    <div className="insight-card-expand-hint">
                      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M15 3h6v6"></path>
                        <path d="M10 14 21 3"></path>
                      </svg>
                      Daha Fazla Göster
                    </div>
                  </>
                )}
              </div>

              <div 
                className="mood-insight-card"
                onClick={() => openInsightModal('thinkingStyle')}
              >
                {isInsightsLoading ? (
                  <InsightLoadingSkeleton 
                    icon="🧠" 
                    title="Düşünme Tarzı" 
                    color={moodGradients.main}
                  />
                ) : (
                  <>
                    <div className="mood-insight-icon">🧠</div>
                    <h3 className="mood-insight-title">Düşünme Tarzı</h3>
                    <div className="insight-content">
